package net.officefloor.hq.app.grade;

import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a grade that is not one of the sheet's, or one already retired. */
public class ValidateRetireGrade {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody GradeRequest request, Grades grades,
            Out<GradeRetirement> retirement, Out<Actor> actor) throws InvalidSheetRequestException {
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (!Grades.ALL.contains(grade)) {
            throw new InvalidSheetRequestException("The grade must be A, B or C");
        }
        if (grades.isRetired(sheetId, grade)) {
            throw new InvalidSheetRequestException("The grade " + grade + " is already retired");
        }
        retirement.set(new GradeRetirement(sheetId, grade, request.user()));
        actor.set(new Actor(request.user()));
    }
}
package net.officefloor.hq.app.grade;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the retirement is saved, so a refused one writes no audit line. */
public class RecordGradeRetired {
    public void record(@Val GradeRetirement retirement, Audit audit) {
        audit.record("GRADE_RETIRED sheet=" + retirement.sheetId() + " by=" + retirement.by()
                + " grade=" + retirement.grade());
    }
}
package net.officefloor.hq.app.grade;

/** Body of a grade retired on the sheet: the grade and who retires it. */
public record GradeRequest(String grade, String user) {
}
package net.officefloor.hq.app.settings;

import java.util.Locale;

/** A user name's role on a sheet: a clerk (the default for any name), a steward, a viewer (who sees
 *  everything and can change nothing), or a restricted clerk (whose people list holds only the people
 *  of the crews they lead or belong to, and themselves). */
public enum Role {
    CLERK, STEWARD, VIEWER, RESTRICTED;

    public String show() {
        return name().toLowerCase(Locale.ROOT);
    }
}
